using System.Runtime.InteropServices;

class EnvVarCheck
{
    /// <summary>
    /// Checks whether an environment variable is defined in /proc/self/environ,
    /// which preserves the distinction between unset and empty on Linux even
    /// under .NET 9's new behaviour.
    /// </summary>
    static bool IsEnvVarDefinedLinux(string name)
    {
        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            var prefix = name + "=";
            return environ.Split('\0').Any(e => e == name || e.StartsWith(prefix));
        }
        catch
        {
            return Environment.GetEnvironmentVariable(name) != null;
        }
    }

